INSERT INTO questions (id, difficulty, category, client_name, client_role, client_icon, project_name, request_text, reply_text, reply_reading, reply_chunks) VALUES ('a08', 'advanced', 'UI', '株式会社 Northstar', '佐藤 / Web 担当', '北', 'スマホ購入導線', '購入ボタンがキーボードで隠れる、と再度連絡が来ました。今日中に仮対応できますか？', '今日中に仮対応します。ボタン位置を固定して、余白を足します。恒久対応は PR #128 にまとめます。', 'きょうじゅうにかりたいおうします。ぼたんいちをこていして、よはくをたします。こうきゅうたいおうは PR #128 にまとめます。', '[{"text":"今日中","kana":"きょうじゅう"},{"text":"に仮対応","kana":"にかりたいおう"},{"text":"します。","kana":"します。"},{"text":"ボタン位置","kana":"ぼたんいち"},{"text":"を固定","kana":"をこてい"},{"text":"して、余白","kana":"して、よはく"},{"text":"を足","kana":"をた"},{"text":"します。","kana":"します。"},{"text":"恒久対応","kana":"こうきゅうたいおう"},{"text":"は PR #128","kana":"は PR #128"},{"text":" にまとめます。","kana":" にまとめます。"}]');
